        "solution": "Maddenin kimliğinin/türünün değişmesi için \"Kimyasal (Güçlü)\" bir bağın kopması veya oluşması gerekir.\nI. Metalik bağ $\\rightarrow$ Güçlü etkileşim (Değiştirir). (Aslında erime-kaynama istisnası vardır, metal erirken kimliği değişmez ama koptuğunda (örn: reaksiyona girdiğinde) güçlü bağdır, cevapta sadece kovalent de olabilir, dikkatli inceleyelim).\n*Düzeltme: Metalik bağ kırıldığında (örneğin demir eridiğinde) kimliği değişmez (sadece hâl değişir). Ama Kovalent ve İyonik koptuğunda kimlik KESİN değişir. Şıklara bakalım.*\nSoru kökünde \"Güçlü Etkileşimler (I ve III) koptuğunda bileşik bozulabilir\". İyon-dipol (II) sadece tuzun suda çözünmesidir, fizikseldir, kimlik değişmez.\nEğer I'i (Metalik bağ koptuğunda kimlik değişir mi?) katı bir şekilde kovalent ile bir tutarsak yanlış olabilir. TYT müfredatında Metalik Bağ sadece fiziksel değişimi (erime/kaynama) belirlediği için maddenin kimliğini (formülünü) değiştirmez! Yalnızca Kovalent veya İyonik bağ koptuğunda bileşik (örneğin H2O, NaCl) parçalanır. Bu çok ince bir detaydır. Kovalent bağ koptuğunda madde (molekül) parçalanır, formülü/türü (kimliği) bozulur.\nDolayısıyla Yalnız III (B seçeneği) en bilimsel cevaptır. Ancak TYT müfredatı Güçlü Etkileşimleri \"Kimyasal Bağ\" kabul ettiği için, (Kimyasal bağ koptuğunda kimlik değişir genel yargısından) cevap C de verilebilir. Net bir soru için Yalnız III en doğrusudur. Burada I'i almadık çünkü metal eridiğinde yine metaldir.\n- **Doğru Seçenek:** B. (Metalik bağ koptuğunda erime olur, kimlik değişmez. Kovalent bağ koptuğunda molekül parçalanır, tür değişir)."
