        "question": "Kovalent bağ, ametal atomlarının elektronlarını ortaklaşa kullanmasıyla oluşur.\nBuna göre, aşağıda verilen element çiftlerinden hangisi aralarında kovalent bağlı bir bileşik oluşturur?\n*(Not: 1A'dan Hidrojen ametaldir, 1A'nın geri kalanı metaldir. 2A, 3A metaldir (Bor hariç). 4A, 5A, 6A, 7A ametaldir).*",
