            "id": "B",
            "text": "Ametallerin elektronegatifliklerinin yüksek olması nedeniyle elektron verme yeteneklerinin olmaması, sadece ortaklaşa kullanarak oktete ulaşabilmeleri. Metallerin ise oktetlerini elektron vererek veya elektron denizinde kalarak sağlamaları."
