        "solution": "Metalik bağın kuvveti, metal atomunun ÇAPIYLA TERS orantılıdır. Çap büyüdükçe (çekirdekler uzaklaştıkça) çekirdeğin elektron denizini tutma gücü ZAYIFLAR.\nLi, Na, K hepsi 1A grubundadır (Yukarıdan aşağıya doğru).\nEn yukarıda çapı en küçük olan Lityum (Li)'dur. Çapı en küçük olduğu için metalik bağı en sağlam, dolayısıyla ERİME NOKTASI EN YÜKSEK olan Li'dir.\nEn aşağıda çapı en büyük olan Potasyum (K) ise en zayıf metalik bağa ve en düşük erime noktasına sahiptir.\nSıralama: $Li > Na > K$ (A). (Metallerin erime noktası ametallerin tam tersi eğilim gösterir)."
