        "id": "KIM-TYT-K03-T26-S02",
        "question": "Ahmet Öğretmen, laboratuvarda öğrencilerine bazı değişimlerin fiziksel mi kimyasal mı olduğunu soruyor:\n1. Gümüş telin elektriği iletmesi (İletkenlik sonrası tel aynı gümüştür)\n2. Tuzlu suyun elektriği iletmesi (Elektroliz ile klor gazı çıkar)\n3. İyot ($I_2$) katısının süblimleşmesi\n4. Kalsiyum karbonat ($CaCO_3$) katısının ısıtılarak ayrışması\nBu olayların \"Fiziksel (F)\" ve \"Kimyasal (K)\" olarak sınıflandırılması aşağıdakilerin hangisinde doğru verilmiştir?",
