        "correctAnswer": "A",
        "difficulty": "medium",
        "solution": "1. Metallerin (gümüş, bakır) iletkenliği sadece serbest elektron hareketidir. Metal kimyasal yapıya zarar vermez. (FİZİKSEL).\n2. İyonik çözeltilerin (tuzlu su) iletkenliği elektrolizdir. İyonlar anoda/katoda gider, madde $Cl_2$, $H_2$ gazı gibi şeylere parçalanır. (KİMYASAL).\n3. Süblimleşme bir hâl değişimidir. (FİZİKSEL).\n4. $CaCO_3$ katısının ısıyla (parçalanarak) $CaO$ ve $CO_2$'ye dönüşmesi bir kimyasal bozulmadır. (KİMYASAL).\nSırasıyla: F - K - F - K (A)."
