        "question": "Aşağıda, kimyasal değişimler sırasında sıklıkla gözlenen bazı olaylar (kanıtlar) verilmiştir.\nAncak bu kanıtlardan bazıları fiziksel değişimlerde de (tesadüfen) görülebilir.\nAşağıdakilerden hangisi **fiziksel bir değişim sırasında da** gözlemlenebilen bir olaydır?",
