        "solution": "K (Potasyum) ve S (Kükürt). S sona geldiğinde \"Sülfat veya sülfit (oksijenli kök)\" değil, \"SÜLFÜR\" diye okunur. $\\rightarrow$ Potasyum sülfür.\nAl (Alüminyum) ve P (Fosfor). P sona geldiğinde \"Fosfat (oksijenli kök)\" değil, \"FOSFÜR\" diye okunur. $\\rightarrow$ Alüminyum fosfür.\nCevap B seçeneğidir. (Latince sayılar di/tri kullanılmaz çünkü bunlar iyonik bileşiktir)."
