        "question": "İki elementten oluşan ikili bileşiklerde, oksijenin $-1$ değerliğini aldığı durumlara \"peroksit\" denir. (Oksijen peroksitlerde $O_2^{-2}$ kökü hâlindedir). Bu durum genellikle 1A ve 2A grubu metalleriyle oluşur.\nBuna göre, aşağıda formülü verilen bileşiklerden hangisi bir **peroksit**tir?\n*(İpucu: Elementin alması gereken normal değerliği düşünerek oksijene ne kaldığını hesaplayın).*",
